-- 086 — Reprise de WeRoof (sinistres et suivi des travaux) dans les sinistres du pilotage, et rattrapage des impayés Monday (demandes de Nicolas du 26/10).
--
-- 1. WeRoof (UDI GESTION, tables public.sinistres, public.suivi_travaux et public.interventions du même projet) :
--    64 dossiers repris (17 en cours, les autres clos), à côté des dossiers Monday, avec le fil des interventions comme mises à jour.
--    Les 3 doublons confirmés par Nicolas (33 bd Henri Dunant, 1 rue des Remparts, 83 rue de la Papeterie) ne sont pas recréés :
--    leurs interventions WeRoof sont ajoutées aux dossiers Monday correspondants.
--    Rattachement aux baux, lots et mandats Rivage par l'adresse et le locataire (méthode gardée dans « rattachement ») ;
--    sans locataire, le dossier est rattaché au lot (adresse à un seul lot) ou au mandat seulement, jamais à un bail deviné.
--    Les dossiers WeRoof prennent un identifiant interne négatif dans pilotage.travaux_monday (table des dossiers repris, colonne origine).
-- 2. Impayés Monday (tableau « UDI Gestion - Suivi IMPAYES ») modifiés depuis l'import du 15/10 :
--    6 nouveaux dossiers créés le 16/10, 10 dossiers mis à jour (une valeur Monday ne remplace jamais une valeur par un vide),
--    nouvelles mises à jour Monday ajoutées au fil (texte complet, liens entiers).
-- Rien n'est écrit dans Rivage ni dans WeRoof. Rejouable sans doublon.

begin;

-- ===== 1. Dossiers repris de WeRoof =====
alter table pilotage.travaux_monday add column if not exists origine text not null default 'monday';
alter table pilotage.travaux_monday add column if not exists weroof_id uuid unique;
alter table pilotage.travaux_monday add column if not exists reference text;
alter table pilotage.travaux_monday add column if not exists description text;
alter table pilotage.travaux_monday_notes add column if not exists weroof_id uuid unique;
comment on column pilotage.travaux_monday.monday_id is 'Identifiant du dossier repris : id de l''élément Monday, ou nombre négatif pour un dossier WeRoof (voir weroof_id).';

insert into pilotage.travaux_monday (monday_id, origine, weroof_id, reference, titre, groupe, clos, statut_monday, bail_id, lot_id, mandat_id, rattachement,
  locataire, adresse, bailleur, entreprises, gestionnaire, intervention_le, cree_le, clos_le, description)
select monday_id, origine, weroof_id, reference, titre, groupe, clos, statut_monday, bail_id, lot_id, mandat_id, rattachement,
  locataire, adresse, bailleur, coalesce(entreprises, '[]'::jsonb), gestionnaire, intervention_le, cree_le, clos_le, description
