"a5422904-0120-4a65-aa06-8de87dc06bad", "auteur": "Marion Brenot", "le": "2026-10-19T00:00:00+00:00", "contenu": "Intervention du 19/10/2026 — Carrelage\nfuite à la douche"}, {"cle": -54, "weroof_id": "e565d34e-f1e4-49e6-8181-895713898cb8", "auteur": "Marion Brenot", "le": "2026-10-19T00:00:00+00:00", "contenu": "Intervention du 19/10/2026 — Plomberie\nrefoulement eau usées dans douche et evier"}, {"cle": -55, "weroof_id": "fa81f0d8-cecb-4163-9ac4-fe59cf50e3ea", "auteur": "Marion Brenot", "le": "2026-10-19T00:00:00+00:00", "contenu": "Intervention du 19/10/2026 — Chauffage\nentretien chaudiere"}, {"cle": -56, "weroof_id": "4fbfd076-f7e9-42ee-af0e-e737501c0ffa", "auteur": "Marion Brenot", "le": "2026-10-20T00:00:00+00:00", "contenu": "Intervention du 20/10/2026 — renovation appartement"}, {"cle": -57, "weroof_id": "6b79972d-2818-473f-b27d-0b99cef3fd48", "auteur": "Marion Brenot", "le": "2026-10-20T00:00:00+00:00", "contenu": "Intervention du 20/10/2026 — Entretien\npréence de cafards"}, {"cle": -60, "weroof_id": "8bd12391-2b4e-4533-867f-25c0a1896580", "auteur": "Marion Brenot", "le": "2026-06-19T14:08:00+00:00", "contenu": "Intervention du 19/06/2026 — Prise de Rdv pour recherche de fuite\nJ'ai contacté le syndic ce jour, pour donner accès au plombier pour faire la recherche de fuite. Ils doivent nous confirmer pour une intervention  lundi 22 juin  à 10h."}, {"cle": -60, "weroof_id": "f9f0620c-738e-49ea-b930-0fa144a29727", "auteur": "Marion Brenot", "le": "2026-06-26T07:19:00+00:00", "contenu": "Intervention du 26/06/2026 — Demande d'investigation dans le local\nJ'autorise ce jour le syndic a investiguer depuis le plafond du local"}, {"cle": 18040678639, "weroof_id": "f62c9dac-9557-4eb6-ba3b-246072332bb6", "auteur": "Reprise WeRoof", "le": "2026-09-01T13:24:05.497802+00:00", "contenu": "Dossier également saisi dans WeRoof (SIN-MTIP7UE3-RB4), confirmé comme doublon de ce dossier par Nicolas le 26/10/2026 : ses interventions sont reprises ici."}]$d$::jsonb) as x(cle bigint, weroof_id uuid, auteur text, le timestamptz, contenu text)
where exists (select 1 from pilotage.travaux_monday t where t.monday_id = x.cle)
  and not exists (select 1 from pilotage.travaux_monday_notes n where n.monday_id = x.cle and (n.weroof_id = x.weroof_id or (x.weroof_id is null and n.contenu = x.contenu)))
on conflict do nothing;

-- Liste des sinistres : origine, référence et description des dossiers repris
do $$
declare
  def text; n int;
  ancien text := $a$'id', 'monday_' || t.monday_id, 'source', 'monday', 'monday_id', t.monday_id, 'numero', null, 'titre', t.titre, 'description', null,$a$;
  nouveau text := $a$'id', 'monday_' || t.monday_id, 'source', 'monday', 'origine', t.origine, 'reference', t.reference, 'monday_id', t.monday_id, 'numero', null, 'titre', t.titre, 'description', t.description,$a$;
begin
  select pg_get_functiondef('public.pilotage_sinistres'::regproc) into def;
  n := (length(def) - length(replace(def, ancien, ''))) / length(ancien);
  if n <> 1 then raise exception 'Critère attendu trouvé % fois dans pilotage_sinistres (1 attendu) : rien n''est modifié', n; end if;
  execute replace(def, ancien, nouveau);
end $$;

