insert into pilotage.impayes (monday_id, groupe, titre, cause, intervenants, responsable, notif_bailleur, declaration_le, garantie, procedure, audience_le,
  maj_assureur_le, prise_en_charge, montant_impaye, indemnisation_recue, indemnite_versee_bailleur, dette_remb_loc, solde_a_rembourser_assureur,
  indemnisation_a_rembourser, observations, commandement_le, bailleur_nom, adresse, mail_bailleur_1, locataire_nom, tel_locataire, cree_le, maj_le)
select x.monday_id, x.groupe, x.titre, x.cause, x.intervenants,
  (select m.user_id from pilotage.membres m where lower(m.prenom) = lower(split_part(trim(split_part(x.intervenants, ',', 1)), ' ', 1)) limit 1),
  x.notif_bailleur, x.declaration_le, x.garantie, x.procedure, x.audience_le, x.maj_assureur_le, x.prise_en_charge, x.montant_impaye,
  x.indemnisation_recue, x.indemnite_versee_bailleur, x.dette_remb_loc, x.solde_a_rembourser_assureur, x.indemnisation_a_rembourser,
  x.observations, x.commandement_le, x.bailleur_nom, x.adresse, x.mail_bailleur_1, x.locataire_nom, x.tel_locataire, x.cree_le, x.cree_le
from imp_monday x where x.nouveau
on conflict (monday_id) do nothing;

insert into pilotage.impayes_actions (impaye_id, libelle, statut, le)
select i.id, a->>'libelle', coalesce(a->>'statut', 'À faire'), (a->>'le')::date
from imp_monday x join pilotage.impayes i on i.monday_id = x.monday_id, jsonb_array_elements(coalesce(x.actions, '[]'::jsonb)) a
where x.nouveau and not exists (select 1 from pilotage.impayes_actions e where e.impaye_id = i.id and e.libelle = a->>'libelle');

-- Dossiers déjà importés : la valeur Monday remplace celle du pilotage, sauf si elle est vide
update pilotage.impayes i set
  groupe = coalesce(x.groupe, i.groupe), titre = coalesce(x.titre, i.titre), cause = coalesce(x.cause, i.cause),
  intervenants = coalesce(x.intervenants, i.intervenants), notif_bailleur = coalesce(x.notif_bailleur, i.notif_bailleur),
  declaration_le = coalesce(x.declaration_le, i.declaration_le), garantie = coalesce(x.garantie, i.garantie), procedure = coalesce(x.procedure, i.procedure),
  audience_le = coalesce(x.audience_le, i.audience_le), maj_assureur_le = coalesce(x.maj_assureur_le, i.maj_assureur_le),
  prise_en_charge = coalesce(x.prise_en_charge, i.prise_en_charge), montant_impaye = coalesce(x.montant_impaye, i.montant_impaye),
  indemnisation_recue = coalesce(x.indemnisation_recue, i.indemnisation_recue), indemnite_versee_bailleur = coalesce(x.indemnite_versee_bailleur, i.indemnite_versee_bailleur),
  dette_remb_loc = coalesce(x.dette_remb_loc, i.dette_remb_loc), solde_a_rembourser_assureur = coalesce(x.solde_a_rembourser_assureur, i.solde_a_rembourser_assureur),
  indemnisation_a_rembourser = coalesce(x.indemnisation_a_rembourser, i.indemnisation_a_rembourser), observations = coalesce(x.observations, i.observations),
  commandement_le = coalesce(x.commandement_le, i.commandement_le), bailleur_nom = coalesce(x.bailleur_nom, i.bailleur_nom), adresse = coalesce(x.adresse, i.adresse),
  mail_bailleur_1 = coalesce(x.mail_bailleur_1, i.mail_bailleur_1), locataire_nom = coalesce(x.locataire_nom, i.locataire_nom),
  tel_locataire = coalesce(x.tel_locataire, i.tel_locataire)
from imp_monday x
where i.monday_id = x.monday_id and not x.nouveau;

-- Mises à jour Monday : messages d'abord, réponses ensuite
