join pilotage.impayes i on i.monday_id = x.monday_id
where x.parent_post_id is not null
on conflict (monday_post_id) do nothing;

update pilotage.impayes d
   set maj_le = greatest(d.maj_le, coalesce((select max(le) from pilotage.impayes_notes n where n.impaye_id = d.id), d.maj_le))
 where d.monday_id in (select monday_id from imp_monday);

commit;

-- Contrôles (attendu : 64 dossiers WeRoof dont 17 en cours ; 237 impayés repris de Monday)
select origine, clos, count(*) dossiers, count(bail_id) avec_bail, count(*) filter (where bail_id is null and coalesce(lot_id, mandat_id) is not null) lot_ou_mandat,
       count(*) filter (where coalesce(bail_id, lot_id, mandat_id) is null) sans_rattachement,
       (select count(*) from pilotage.travaux_monday_notes n join pilotage.travaux_monday t2 on t2.monday_id = n.monday_id where t2.origine = t.origine and t2.clos = t.clos) mises_a_jour
from pilotage.travaux_monday t group by origine, clos order by origine, clos;
select (select count(*) from pilotage.impayes where monday_id is not null) impayes_monday,
       (select count(*) from pilotage.travaux_monday_notes where weroof_id is not null and monday_id > 0) interventions_sur_doublons;
